"0.9"></line><line x1="400" y1="500" x2="712.1320343559642" y2="287.86796564403573" stroke="rgba(197, 154, 69, 0.25)" stroke-width="0.9"></line><line x1="429.28932188134524" y1="429.28932188134524" x2="800" y2="499.99999999999994" stroke="rgba(197, 154, 69, 0.25)" stroke-width="0.9"></line><line x1="500" y1="400" x2="712.1320343559645" y2="712.132034355964" stroke="rgba(197, 154, 69, 0.25)" stroke-width="0.9"></line><line x1="570.7106781186548" y1="429.28932188134524" x2="500.0000000000001" y2="800" stroke="rgba(197, 154, 69, 0.25)" stroke-width="0.9"></line></g><circle cx="729.8133329356934" cy="307.16371709403825" r="9" fill="rgba(197, 154, 69, 0.35)"></circle><circle cx="377.8703541595575" cy="645.5484441926058" r="7" fill="none" stroke="rgba(197, 154, 69, 0.4)" stroke-width="1.2"></circle><circle cx="105.32909926991846" cy="356.35153980321917" r="6" fill="rgba(197, 154, 69, 0.3)"></circle><circle cx="200" cy="500.00000000000006" r="8" fill="none" stroke="rgba(197, 154, 69, 0.3)" stroke-width="1.2" stroke-dasharray="2 2"></circle><circle cx="769.9707960683465" cy="178.26133389002916" r="6" fill="rgba(197, 154, 69, 0.35)"></circle><g transform="translate(577.6457135307562 789.7777478867205) scale(1.2)" class="sky-star"><path d="M0 -24 L1.4 -1.4 L10 0 L1.4 1.4 L0 24 L-1.4 1.4 L-10 0 L-1.4 -1.4 Z"></path><path d="M-4.5 -4.5 L4.5 4.5 M4.5 -4.5 L-4.5 4.5" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="0.8"></path></g><g transform="translate(289.9999999999998 136.26933041053582) scale(1.4)" class="sky-star"><path d="M0 -24 L1.4 -1.4 L10 0 L1.4 1.4 L0 24 L-1.4 1.4 L-10 0 L-1.4 -1.4 Z"></path><path d="M-4.5 -4.5 L4.5 4.5 M4.5 -4.5 L-4.5 4.5" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="0.8"></path></g><g transform="translate(683.5259069949229 549.175618569479) scale(1.1)" class="sky-star"><path d="M0 -24 L1.4 -1.4 L10 0 L1.4 1.4 L0 24 L-1.4 1.4 L-10 0 L-1.4 -1.4 Z"></path><path d="M-4.5 -4.5 L4.5 4.5 M4.5 -4.5 L-4.5 4.5" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="0.8"></path></g></svg><div class="program-main"><h1 id="page-title">Personalised Hand Holding Program</h1><p>Knowing what to change is one part of it. Following through takes time. Work with Narayani over six months, with space to ask, reflect and try again.</p><div class="cta-row"><a href="/contact/?topic=the%20Personalised%20Hand%20Holding%20Program" class="button button-light" data-enquiry="" data-topic="the Personalised Hand Holding Program" data-source="program-hero" aria-haspopup="dialog" data-primary-cta="">Enquire about the program</a></div><p class="program-note">Format and fees are discussed before you decide.</p></div><div class="program-details"><div class="program-duration"><strong>6</strong><span>months of personal guidance</span></div><ul><li>Calls and messages through the six months</li><li>Space to revisit, reflect and ask</li><li>All four areas, together</li></ul><div class="program-domains"><span>Health</span><span>Relationship</span><span>Career</span><span>Money</span></div></div></div></section><section class="section-wrap section-space approach-grid" aria-labelledby="for-title"><div class="approach-intro"><h2 id="for-title">Who the program is for</h2><p>Some patterns take time to understand and change. The program gives you ongoing guidance while you work through them in everyday life.</p><figure class="pattern-path"><svg viewBox="0 0 480 210" fill="none" aria-hidden="true"><path d="M20 154 C80 154 61 45 129 45 C199 45 212 164 142 168 C66 172 77 66 148 74 C202 80 189 135 154 133 C122 131 129 98 157 108 C202 132 226 142 275 114 C324 85 335 64 374 64 L449 64" stroke="var(--art)" stroke-width="1.6"></path><path d="M20 173 C90 173 235 171 301 133 C349 105 383 86 449 86" stroke="var(--art)" stroke-opacity=".22" stroke-width="1"></path><circle cx="155" cy="113" r="5" fill="var(--detail)"></circle><circle cx="374" cy="64" r="6" fill="var(--paper)" stroke="var(--detail)"></circle><path d="m442 58 7 6-7 6" stroke="var(--detail)" stroke-width="1.5"></path></svg><figcaption>A familiar pattern. A different way forward.</figcaption></figure></div><div class="fit-list"><ul class="fit-items"><li>The same pattern keeps returning, in more than one area of life.</li><li>A big decision is coming, and you want steady guidance through it.</li><li>You would rather have someone stay with you than a single reading.</li><li>Your family is part of the question too.</li></ul><a href="/contact/?topic=the%20Personalised%20Hand%20Holding%20Program" class="text-link" data-enquiry="" data-topic="the Personalised Hand Holding Program" data-source="program-for-you" aria-haspopup="dialog">Ask whether it suits you</a></div></section><section class="band" aria-labelledby="how-title"><div class="section-wrap section-space split"><div><h2 id="how-title">How the six months work</h2><p>The details are agreed with you at the start, around your life and your questions.</p><div class="figure-box"><svg viewBox="0 0 320 320" class="areas-figure areas-figure" role="img" aria-label="One life at the centre, with health, relationship, career and money around it" data-draw="" data-art="areas"><g class="chakra-outer-spin" style="transform-origin:160px 160px"><circle cx="160" cy="160" r="140" fill="none" stroke="var(--detail)" stroke-width="0.8" stroke-dasharray="3 6" opacity="0.5"></circle><circle cx="160" cy="160" r="132" fill="none" stroke="var(--art)" stroke-width="1.4"></circle><circle cx="160" cy="160" r="110" fill="none" stroke="var(--detail)" stroke-width="0.7" stroke-dasharray="2 4" opacity="0.4"></circle><path d="M160 20v100M160 200v100M20 160h100M200 160h100" fill="none" stroke="var(--art)" stroke-width="1.2" opacity="0.6"></path><g fill="var(--detail)" class="chakra-nodes"><rect x="156" y="24" width="8" height="8" transform="rotate(45 160 28)"></rect><rect x="156" y="288" width="8" height="8" transform="rotate(45 160 292)"></rect><rect x="24" y="156" width="8" height="8" transform="rotate(45 28 160)"></rect><rect x="288" y="156" width="8" height="8" transform="rotate(45 292 160)"></rect></g></g><g fill="none" stroke="var(--art)" stroke-width="1.4"><circle cx="160" cy="160" r="86" opacity=".45" class="chakra-pulse-ring" style="transform-origin:160px 160px"></circle><circle cx="160" cy="160" r="40" class="chakra-center-ring" style="transform-origin:160px 160px"></circle></g><g font-size="19" text-anchor="middle" font-style="italic" class="chakra-labels"><text x="104" y="98">Health</text><text x="216" y="98">Relationship</text><text x="104" y="234">Career</text><text x="216" y="234">Money</text></g><text x="160" y="165" text-anchor="middle" class="centre-label chakra-center-you">YOU</text></svg></div></div><ol class="timeline process-timeline"><li><span class="process-thread" aria-hidden="true"></span><span class="timeline-dot">1</span><div><h3>Begin with the whole picture</h3><p>A first, full conversation about your questions, your circumstances, your numbers, chart and surroundings.</p></div></li><li><span class="process-thread" aria-hidden="true"></span><span class="timeline-dot">2</span><div><h3>Calls through the months</h3><p>One-on-one calls with Narayani across the six months, at a rhythm you agree at the start.</p></div></li><li><span class="process-thread" aria-hidden="true"></span><span class="timeline-dot">3</span><div><h3>Messages in between</h3><p>Write when something comes up, from a hard day to an everyday choice.</p></div></li><li><span class="process-thread" aria-hidden="true"></span><span class="timeline-dot">4</span><div><h3>All four areas, together</h3><p>Health, relationship, career and money, looked at as one life.</p></div></li></ol></div></section><section class="section-wrap section-space" aria-labelledby="compare-title"><div class="section-heading centered"><h2 id="compare-title">A consultation or the program?</h2><p>Not sure which suits you? Ask, and the team will tell you honestly.</p></div><div class="compare"><div><h3>Consultation</h3><p>One focused conversation, around a single question.</p><ul><li>Online or in person</li><li>A clear next step</li></ul><a href="/contact/" class="button button-ghost" data-enquiry="" data-source="program-compare-consultation" aria-haspopup="dialog">Enquire about a consultation</a></div><div><h3>Hand Holding Program</h3><p>Six months of guidance, with all four areas looked at together.</p><ul><li>Calls, with messages in between</li><li>Room to revisit as life changes</li></ul><a href="/contact/?topic=the%20Personalised%20Hand%20Holding%20Program" class="button button-light" data-enquiry="" data-topic="the Personalised Hand Holding Program" data-source="program-compare-program" aria-haspopup="dialog">Enquire about the program</a></div></div></section><section class="band" aria-labelledby="stays-title"><div class="section-wrap section-space"><div class="transformation-head"><div><h2 id="stays-title">Guidance that stays</h2></div></div><div class="stays-grid"><div class="stays-left-narrative"><figure class="quote-band"><span class="quote-mark" aria-hidden="true">“</span><blockquote><p>Whenever we have to take a major decision, we consult her, and she tells us the broader picture. The response is so accurate, and the availability is amazing.</p></blockquote><figcaption class="client"><div>Navleen S.<small>Family, after 12 years in Australia</small></div></figcaption></figure><div class="stays-extended-desc"><p>True inner calibration shifts how you navigate uncertainty, manage high-stakes decisions, and nurture deep relationships without losing your peace.</p><ul class="stays-key-takeaways"><li><strong>Sustained Intuitive Clarity:</strong> Recognize personal karmic triggers early and make proactive decisions with confidence instead of reactive hesitation.</li><li><strong>Harmonious Relationship Dynamics:</strong> Balance interpersonal energies with gentle Vedic alignment and mindset rewiring that restores household peace.</li><li><strong>Long-Term Strategic Blueprint:</strong> Lifetime access to your personalized astrological patterns and foundational remedies for ongoing growth.</li></ul></div></div><div class="program-films"><div class="reel-track" tabindex="0" role="region" aria-label="Client films about ongoing guidance"><figure class="reel"><div class="reel-frame"><img src="/images/testimonials/new-1.webp" alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer"/><span class="reel-duration">1:36</span><button type="button" class="reel-play" aria-label="I was completely lost. Watch their story: A client&#x27;s reflection, 1:36" data-title="A client&#x27;s reflection: Finding her own direction"><span class="reel-hook">I was completely lost</span><span class="reel-play-icon" aria-hidden="true"><svg viewBox="0 0 12 14"><path d="M0 0l12 7-12 7z"></path></svg></span><span>Watch their story</span></button></div><figcaption><strong>Finding her own direction</strong><span>A client&#x27;s reflection<!-- --> · <!-- -->Three years of guidance</span></figcaption></figure><figure class="reel"><div class="reel-frame"><img src="/images/testimonials/new-2.webp" alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer"/><span class="reel-duration">0:46</span><button type="button" class="reel-play" aria-label="Through the best and worst. Watch their story: A client&#x27;s reflection, 0:46" data-title="A client&#x27;s reflection: Someone to turn to"><span class="reel-hook">Through the best and worst</span><span class="reel-play-icon" aria-hidden="true"><svg viewBox="0 0 12 14"><path d="M0 0l12 7-12 7z"></path></svg></span><span>Watch their story</span></button></div><figcaption><strong>Someone to turn to</strong><span>A client&#x27;s reflection<!-- --> · <!-- -->Five years of guidance</span></figcaption></figure><figure class="reel"><div class="reel-frame"><img src="/images/testimonials/client-2.webp" alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer"/><span class="reel-duration">1:01</span><button type="button" class="reel-play" aria-label="When our confidence broke. Watch their story: Renu S., 1:01" data-title="Renu S.: A way out of a hard year"><span class="reel-hook">When our confidence broke</span><span class="reel-play-icon" aria-hidden="true"><svg viewBox="0 0 12 14"><path d="M0 0l12 7-12 7z"></path></svg></span><span>Watch their story</span></button></div><figcaption><strong>A way out of a hard year</strong><span>Renu S.<!-- --> · <!-- -->Through a difficult year</span></figcaption></figure><figure class="reel"><div class="reel-frame"><img src="/images/testimonials/client-4.webp" alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer"/><span class="reel-duration">1:20</span><button type="button" class="reel-play" aria-label="I was all over the place. Watch their story: Shelley, 1:20" data-title="Shelley: From London"><span class="reel-hook">I was all over the place</span><span class="reel-play-icon" aria-hidden="true"><svg viewBox="0 0 12 14"><path d="M0 0l12 7-12 7z"></path></svg></span><span>Watch their story</span></button></div><figcaption><strong>From London</strong><span>Shelley<!-- --> · <!-- -->London, about seven years</span></figcaption></figure></div><div class="track-controls"><div class="track-progress" aria-hidden="true"><i class="is-current"></i><i></i><i></i><i></i></div><button type="button" aria-label="Previous film" disabled="">←</button><span aria-live="polite">1<!-- --> / <!-- -->4</span><button type="button" aria-label="Next film">→</button></div></div></div></div></section><section class="faq-wrap has-backdrop" aria-labelledby="faq-title"><svg class="backdrop backdrop-vastu " viewBox="0 0 300 300" aria-hidden="true" focusable="false"><rect x="30" y="30" width="240" height="240" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="1.1"></rect><path d="M56.66666666666667 30V270M30 56.66666666666667H270M83.33333333333334 30V270M30 83.33333333333334H270M110 30V270M30 110H270M136.66666666666669 30V270M30 136.66666666666669H270M163.33333333333334 30V270M30 163.33333333333334H270M190 30V270M30 190H270M216.66666666666669 30V270M30 216.66666666666669H270M243.33333333333334 30V270M30 243.33333333333334H270" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="0.7" class="sky-faint"></path><rect x="110" y="110" width="80" height="80" fill="none" stroke="currentColor" vector-effect="non-scaling-stroke" stroke-width="1.1"></rect><circle cx="150" cy="150" r="4" class="sky-ink"></circle><text x="150" y="14" class="sky-direction" text-anchor="middle" dominant-baseline="central">N</text><text x="282" y="18" class="sky-direction" text-anchor="middle" dominant-baseline="central">NE</text><text x="288" y="150" class="sky-direction" text-anchor="middle" dominant-baseline="central">E</text><text x="282" y="284" class="sky-direction" text-anchor="middle" dominant-baseline="central">SE</text><text x="150" y="288" class="sky-direction" text-anchor="middle" dominant-baseline="central">S</text><text x="18" y="284" class="sky-direction" text-anchor="middle" dominant-baseline="central">SW</text><text x="12" y="150" class="sky-direction" text-anchor="middle" dominant-baseline="central">W</text><text x="18" y="18" class="sky-direction" text-anchor="middle" dominant-baseline="central">NW</text></svg><div class="faq section-wrap section-space" id="faq"><div class="faq-intro"><h2 id="faq-title">Before you enquire</h2><p>A few things you may want to know first.</p><a href="/contact/" class="text-link" data-enquiry="" data-source="program-faq" aria-haspopup="dialog">Ask something else</a></div><div class="faq-list"><details><summary>How often will we speak?<span aria-hidden="true"></span></summary><p>The rhythm of calls is agreed at the start, around your life. Messages fill the space in between.</p></details><details><summary>Can my family be part of it?<span aria-hidden="true"></span></summary><p>Yes. Many questions involve a partner, children or parents, and the program can take them into account.</p></details><details><summary>Can I start with a single consultation?<span aria-hidden="true"></span></summary><p>Yes. You can begin with one consultation and decide about the program afterwards.</p></details><details><summary>Can I take part from outside India?<span aria-hidden="true"></span></summary><p>Yes. Calls and messages work across time zones. Mention yours when you enquire.</p></details><details><summary>What does the program cost?<span aria-hidden="true"></span></summary><p>The fee depends on the format and is shared when you enquire, before you decide.</p></details><details><summary>Does this replace medical or professional advice?<span aria-hidden="true"></span></summary><p>No. This is personal and spiritual guidance. It does not replace medical care, mental health treatment, legal advice or financial advice from qualified professionals.</p></details></div></div></section><!--$--><!--/$--></main><footer class="site-footer" id="site-footer"><div class="section-wrap"><div class="footer-cta-box"><div class="footer-cta-text"><h2>Start with one conversation</h2><p>Tell her team what is on your mind.</p></div><div><a href="/contact/" class="button-primary footer-cta-btn" data-enquiry="" data-source="footer" aria-haspopup="dialog"><span>Enquire about a consultation</span><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="M5 12h14M12 5l7 7-7 7"></path></svg></a></div></div><div class="footer-content"><div class="footer-brand"><img src="/images/nng-logo-400.webp" alt="Transformation with NNG" width="160" height="84" loading="lazy"/><p><strong>Narayani Garg, The Life Strategist</strong>Mind. Direction. Alignment.</p></div><nav class="footer-nav" aria-label="Footer links"><strong class="footer-col-title">PAGES</strong><a href="/">Home</a><a href="/services/">Services</a><a href="/hand-ho